from state import TokenBucket

def test_bucket_refill_capped():
    b = TokenBucket(3)
    assert b.take(3) is True
    b.refill(10)
    assert b.tokens == 3

def test_bucket_exhausted():
    b = TokenBucket(2)
    b.take(2)
    assert b.take(1) is False


from collect import add_metric

def test_metric_no_leak():
    first = add_metric("x", 1)
    second = add_metric("y", 2)
    assert first == {"x": [1]}
    assert second == {"y": [2]}

def test_metric_explicit_store():
    store = {}
    add_metric("x", 1, store)
    add_metric("x", 2, store)
    assert store == {"x": [1, 2]}

def test_metric_empty_call():
    assert add_metric("x", 0) == {"x": [0]}
